const char *const ui_alarm_catalog_version = "2026-08-14";

const ui_alarm_catalog_entry_t *ui_alarm_catalog_find(uint16_t code)
{
    for(const auto &e : kAlarms) {
        if(e.code == code) {
            return &e;
        }
    }
    return nullptr;
}

const ui_alarm_detail_entry_t *ui_alarm_detail_find(uint32_t detail)
{
    for(const auto &e : kDetails) {
        if(e.code == detail) {
            return &e;
        }
    }
    return nullptr;
}

int ui_alarm_catalog_count(void)
{
    return (int)(sizeof(kAlarms) / sizeof(kAlarms[0]));
}

uint16_t ui_alarm_snapshot_code(uint8_t word_index, uint8_t bit_index)
{
    for(const auto &e : kSnapshotSlots) {
        if(e.word_index == word_index && e.bit_index == bit_index) {
            return e.code;
        }
    }
    return 0;
}

bool ui_alarm_snapshot_slot_of(uint16_t code, uint8_t *word_index,
                               uint8_t *bit_index)
{
    for(const auto &e : kSnapshotSlots) {
        if(e.code != code) {
            continue;
        }
        if(word_index) *word_index = e.word_index;
        if(bit_index)  *bit_index  = e.bit_index;
        return true;
    }
    return false;
}

int ui_alarm_snapshot_count(void)
{
    return (int)(sizeof(kSnapshotSlots) / sizeof(kSnapshotSlots[0]));
}
